"""English, synthetic-only live task log; no secrets or private microphone data."""
import datetime,html,json
from pathlib import Path
from final_verify import runtime_signature

ROOT=Path(__file__).parent
LIVE=Path('/mnt/nvme/robo-speaker-studies/speaker-live-results')

def main():
    def read(path):return json.loads(path.read_text()) if path.exists() else {}
    gaze=read(ROOT/'logs/gaze-rendering-checks.json');desk=read(ROOT/'logs/desk-robot-checks.json')
    prompt=read(ROOT/'logs/prompt-quality-checks.json');unit=read(ROOT/'logs/unit-checks.json')
    stop=read(LIVE/'stop-commands-live.json');mic=read(ROOT/'logs/browser-capture-desk.json')
    active=read(ROOT/'logs/active-todos-verification.json');signature=runtime_signature()
    camera=read(ROOT/'logs/browser-checks.json')
    proactive=read(LIVE/'proactive-live.json');tools=read(ROOT/'logs/interaction-tools-checks.json')
    proactive_visual=read(LIVE/'proactive-visual-live.json');reliability_ui=read(ROOT/'logs/reliability-ui-checks.json')
    semantic=read(ROOT/'logs/semantic-decision-checks.json');ui=read(ROOT/'logs/browser-ui-status.json')
    proactive_ok=bool(proactive.get('passed') and len(proactive.get('cases',[]))>=4 and proactive.get('runtime_source_sha256')==signature)
    stop_ok=bool(stop.get('passed') and len(stop.get('cases',[]))>=8 and stop.get('source_unchanged') and stop.get('runtime_source_sha256')==signature)
    follow=read(ROOT/'logs/follow-pipeline-checks.json')
    onboarding=read(ROOT/'logs/visual-onboarding-checks.json')
    chunks=read(ROOT/'logs/tts-chunk-checks.json')
    onboarding_ok=bool(onboarding.get('passed') and onboarding.get('runtime_source_sha256')==signature
        and {'modest','static'}<=set(c.get('mode') for c in onboarding.get('cases',[])))
    live_follow_ok=bool(proactive_visual.get('passed') and proactive_visual.get('runtime_source_sha256')==signature
        and {'positive','repeated','unknown','disabled','unrelated'}<=set(c.get('condition') for c in proactive_visual.get('cases',[])))
    tasks=[
      ('long-reading-stops',bool(read(LIVE/'stop-commands-live.json').get('passed') and read(LIVE/'stop-commands-live.json').get('runtime_source_sha256')==signature),'Interrupt long spoken answers with current-speaker Stop / wait commands','Separate Stop task phase, bounded native ASR candidates, late-result guards, atomic cancellation and consumed wait commands. Compact/brief commands require explicit crop and acoustic consensus; no arbitrary transcript can bypass current-addressee checks. Synthetic long-reading positives and enrolled/background negatives, including retained misses, are in /static/stop-reading-update.html. This item stays open if the latest replay has a miss.'),
      ('stop-feedback-and-calm-reading',bool(read(ROOT/'logs/stop-controls-browser.json').get('passed') and read(ROOT/'logs/stop-controls-browser.json').get('runtime_source_sha256')==signature),'Optional polite stop feedback and calm, gentle information reading','Silent default; independent persisted checkbox permits four short local acknowledgments, suppressed by waiting/quiet requests, new speech, pending turns, disconnection or a new reply. News/Wikipedia/long explanations request unhurried articulation and pauses in the exact policy/recipe. No measured words-per-minute or human room guarantee. Browser stop/late-packet controls and offline races are tested.'),
      ('speed-model-comparison',bool(read(ROOT/'logs/director-speed-routed.json').get('finished')),'Compare API/local directors and optimize transport without dropping quality','Tested Luna, Mercury 2.5, DeepSeek V4 Flash, Gemini 3.5 Flash-Lite and local Gemma 4 E4B/12B QAT Q4. Luna retained: faster candidates failed real tool/instruction controls. CPU-worker MP3 decoding replaces per-chunk ffmpeg starts for the native format, with measured waveform parity and fallback. Relevant-only tool schemas and longer HTTP keep-alive reduce avoidable work. See /static/speed-and-tools.html for medians, tails, all attempts and honest end-to-end limits.'),
      ('open-speakers',bool(read(ROOT/'logs/open-speakers-browser.json').get('passed') and read(ROOT/'logs/open-speakers-browser.json').get('runtime_source_sha256')==signature),'Optional wake-free foreground enrollment and a one-time name question','New independently persisted checkbox defaults ON. Known-voice recovery precedes clean/coherent new Guest enrollment; final ASR/teacher/echo guards remain. OFF restores wake-required enrollment. Unknown/new foreground is not guaranteed to be addressed to Robby; TV false admissions remain possible. Real HTTPS fake-mic ON/OFF tests and retained greeting failures are in the report.'),
      ('explicit-voice-variants',bool(read(ROOT/'logs/speaker-variant-live.json').get('passed') and read(ROOT/'logs/speaker-variant-live.json').get('runtime_source_sha256')==signature),'Explicitly associate multiple voice anchors with one session person','“It is me, Bob” / “Ich bin es doch, Bob” can attach an unnamed guest to one existing name. Four independent fast/long/teacher anchors maximum; original anchor retained; named users are never silently merged. Local unit and real ASR/ECAPA replay results are reported separately. This trusts a user assertion and is not authentication. A second new guest initially hit the old known-person disagreement veto; the scoped provisional-guest path now installs its own qualified reference.'),
      ('public-information-tools',bool(read(ROOT/'logs/knowledge-browser.json').get('passed') and read(ROOT/'logs/knowledge-browser.json').get('runtime_source_sha256')==signature),'Bounded news, weather and Wikipedia lookups with actual source links','Concurrent official feeds (Tagesschau/BBC/DW/DLF/Guardian), Open-Meteo forecast and MediaWiki search/extracts. Allowlisted HTTPS, bounded responses/timeouts/cache, no arbitrary URL fetching. Unknown weather location is blocked before network access. Sources consulted are visible in chat; claims still require source checking. See /static/speed-and-tools.html and README for provider terms, tests and limitations.'),
      ('longer-streaming-chunks',bool(chunks.get('passed') and chunks.get('runtime_source_sha256')==signature),'Use 1,600-ms TTS chunks and a 450-ms initial playback reserve','Changed normal streaming requests from 10 to 20 semantic frames (80 ms/frame). Fewer per-chunk HTTP downloads and MP3 decoder starts; first audio may take longer. The first test exposed a 337-ms scheduling gap after the short initial codec block, so browser playback now adds a real 450-ms initial reserve once per reply. Backchannels retain device-only lead. Microphone processing remains 320 ms; cancellation still stops queued audio and Second Ear uses actual scheduled positions. Before/after HTTPS browser receipts are logs/tts-chunk-before-reserve.json and logs/tts-chunk-checks.json; not a physical-device listening test.'),
      ('brief-farewell-diagnosis',False,'Investigate dropped short farewells without weakening speaker protection','Code-level reproduction: choose_turn_text(["Bye bye"], "Bye") abstains, while agreeing "Bye bye" readings pass. Bye is absent from the short-word exception list (Ja/Danke/etc.). Short utterances can also fail acoustic identity evidence, especially after diarization loses its known-speaker association. No real user failure was recorded or conclusively attributed, and no identity or word-origin threshold was relaxed. This entry remains open for targeted short-utterance testing/fix.'),
      ('audio-first-camera-options',bool(onboarding_ok and any(c.get('mode')=='audio_default' and c.get('passed') for c in onboarding.get('cases',[]))),'Disable face VAD and webcam Face ID by default without losing gaze or voice memory','Two independent opt-in checkboxes are visible beside the camera controls. Old camera-gating settings migrate OFF. Disabled Face ID terminates its worker and ignores late results; disabled face VAD skips mouth-motion analysis and bypasses only the visual gate. Acoustic enrollment and matching are unchanged. Browser camera-to-head tests check zero Face-ID calls; public HTTPS voice onboarding checks camera ON with both visual recognition options OFF.'),
      ('visible-introduction-recovery',onboarding_ok,'Do not reject modestly articulated introductions as unknown voices','The visual gate was blocking before acoustic identity resolution. Replaced excessive per-frame mouth-motion requirements with time-normalized excursion/reversal checks, clarified timing/face/motion failures and added a visible camera-only recovery button. Packet counters now reset per connection. See /static/visual-onboarding-update.html: actual browser/ASR/enrollment/TTS with synthetic moving landmarks, static-mouth rejection and recovery preserving acoustic recognition. No physical-user accuracy claim.'),
      ('continuous-rule-rearm',live_follow_ok,'Continuous 320-ms decisions and repeated-topic re-arming','Fixed actual 640-ms throttle, unchanged Stop retries and rule latching until silence. New post-playback trigger words can re-arm after four seconds. Literal rules preempt old contextual requests. A bounded same-rule diarization tail no longer creates an extra ordinary response. See /static/live-follow-update.html for real ASR/TTS controls and retained failed attempts.'),
      ('gaze-pipeline-recovery',bool(follow.get('passed')),'Actual camera-to-head path and recovery from frozen/manual state','Real CPU landmark inference on a moving public NASA-image canvas camera drives the actual selection and 3D renderer in all four directions. Resume eye contact exits frozen calibration/manual/tour overrides. Stalled presentation timestamps recover; gaze remains independent of optional gallery failures. This is not a physical perceptual gaze-accuracy study.'),
      ('contextual-interjection',bool(semantic.get('passed')),'Useful conversational interjections, independently switchable','Luna evaluates meaning with conversation history; unchanged text is cached and one request remains outstanding. Brief interjections have a twelve-second cooldown. Laya failed contextual controls and falsely treated continuing speech as Stop; no classifier query is now made on fragments without a stop cue, and ambiguous meaning goes to Luna. Exact rules remain local. See measured API latency and remaining failed controls in the current report.'),
      ('nonblocking-live-audio',live_follow_ok,'Keep identity checks and queued ASR from holding live microphone hops','Native teacher/echo verification is now background single-flight and rechecks reply/identity epochs. Shared GPU lock is reentrant and prioritizes waiting live encoder hops. Long-monologue replay validates no audio_too_fast disconnect in that fixture; not a guarantee under arbitrary GPU contention.'),
      ('reliability-ui',bool(reliability_ui.get('passed')),'Visible camera/follow controls and local person reference gallery','Camera auto-start and position following default ON, subject to browser permission and remembered explicit opt-out. Main actions are at the top; a stable primary face is followed if no unique audio-correlated face is available. Voice/face recognition and reference/current local photos are shown separately. Existing profiles without enrollment images say so; photos require explicit consent for persistence. Fake-device Chromium tests cover defaults, following after face order changes, two-image cards, separate voice/face status, mobile layout and opt-out persistence. See /static/reliability-update.html.'),
      ('retry-live-interruptions',bool(proactive_visual.get('passed') and len(proactive_visual.get('cases',[]))>=4 and proactive_visual.get('runtime_source_sha256')==signature),'Retry uncertain partials; face-corroborated interruption and no duplicate tail','A partial is consumed only after actual admission, so unchanged words can be retried. Four strong checks can recover weak initial acoustic context. A fresh positive Face-ID plus unique time-aligned mouth motion can corroborate the normal UI voice threshold, still requiring teacher, fast and long same-person evidence and rival margins. Incomplete priming contexts are excluded from that route’s qualified mean. Keyword-free tails inside the already-interrupted monologue no longer produce duplicate replies. Brief exact interjections are opportunistically cached in session RAM using the shared TTS. Real ASR/tool/TTS checks with synthetic face signals and negative controls are recorded separately from human accuracy. See /static/reliability-update.html.'),
      ('local-laya',bool(semantic.get('local_model_verified')),'Local multilingual Laya decision model · CPU worker','The likely intended Laia family was identified as Laya through its original repository and Unsloth documentation. The pinned convaiinnovations/laya-multilingual checkpoint now runs in an isolated CPU process on loopback port 8797, four threads, no second GPU model. Its health, source commit, weight revision and policy hash are verified separately from classification accuracy. This spelling/checkpoint choice is an explicit interpretation of the request, not a user-confirmed exact URL. No unrelated Granite server is used.'),
      ('freeform-semantics',bool(any(c.get('case')=='agreed_semantic' and c.get('passed') for c in semantic.get('cases',[]))),'Freeform meaning-dependent rules · experimental, not generally validated','The local model can make fast typed judgments, but zero-shot generic condition matching is not reliably solved. The deliberately forced semantic banana-condition control remains a retained failed development check unless its current receipt says otherwise. Named-topic games use the dedicated keyword tool and do not need that uncertain classifier. More domain examples/fine-tuning and independent validation are needed before promising arbitrary semantic conditions.'),
      ('live-agreements',bool(proactive_ok and tools.get('passed')),'Interrupt the user before their agreed-condition speech ends','Real Luna set_interruption_rule / clear_interruption_rules tools replace promises without executable state. A bounded session-only, owner-scoped rule book validates explicit permission. Fresh native partials trigger local literal rules or semantic decisions; independent acoustic known-speaker proof remains mandatory. Brief interjections skip ordinary turn-end waiting and a new Luna response call, reuse loaded TTS, latch once per ongoing utterance and suppress duplicate late replies. Four live positive/disabled/unrelated/unknown cases must pass on the current source.'),
      ('live-control',bool(ui.get('passed') and any('proactive checkbox' in c for c in ui.get('cases',[]))),'Prominent default-on checkbox and real installed-rule display','The checkbox is above the robot. It controls only Robby interrupting the user, not incoming user stops. The UI displays actual installed conditions and exact interjections, supports Clear agreed rules, and shows the configured controller. Session-only settings do not silently claim a rule survived reconnection.'),
      ('live-decisions',bool(semantic.get('explicit_stop_and_controls_passed') and stop_ok),'Both-stream local stop decisions, with verified identity','On 320-ms hops, single-flight probes and latest-only decisions see user ASR candidates, planned agent text and actual played seconds. The local CPU Laya adapter combines two counterbalanced typed choices with explicit stop-command guards. Acoustic current-addressee/teacher/fast/playback verification still authorizes actions. Native TYGER remains unchanged. An API-only Luna fallback hit its 3-s deadline on all six retained checks and is not the live default. The current streamed positive/foreign-speaker receipt, not successful text classification alone, controls completion.'),
      ('speaker-threshold',bool(gaze.get('speaker_default',{}).get('reset_restores_default')),'Adjustable speaker recognition · default 0.32','Normal sentence-match cosine is now 0.32, with a visible slider, last score, reset and local numeric setting persistence. Custom saved thresholds are preserved; Reset adopts 0.32. A weak new-channel assignment additionally needs independent fast corroboration. This permissive user-requested default is not a human-calibrated security threshold; it can admit background voices. Earlier sensitivity receipts do not validate a false-acceptance rate at 0.32.'),
      ('camera-budget',bool(gaze.get('camera_rate',{}).get('maximum_requested_fps')==10),'Camera capture and CPU landmarks · maximum 10 FPS','Capture requests 640×480 at up to 10 FPS; an independent 100-ms inference interval also bounds CPU work. Animation remains independent and smooth. Actual Chromium fake-camera capture and inference rates are measured below; no physical camera performance is claimed.'),
      ('position-follow',bool(gaze.get('passed')),'Follow eyes, not head rotation','Eye-socket midpoint replaces nose/roll imitation. Aspect-corrected 3-D eye spacing provides a bounded depth heuristic; a small virtual pivot setback accounts for near/far parallax. A 130-ms filter, tremor dead band, bounded head velocity and brief lost-face hold/fade avoid twitching. Emotional lids/brows/mouth remain expressive without overriding eye contact.'),
      ('calibration',bool(gaze.get('passed')),'Local geometric eye-contact calibration','Regularized four-feature regression predicts tangent pan/tilt from eye position and inverse distance. Y confirms. X freezes the observation and expression; arrows adjust pan/tilt; Y saves. Only numeric geometric examples stay in localStorage. Undo, reset, keyboard-input protection and reload persistence are tested. This is a perceptual aid, not measured physical eye-gaze accuracy.'),
      ('guided-tour',bool(gaze.get('ui',{}).get('eight_step_keyboard_tour')),'Large guided keyboard tutorial','Starting faces Robby forward, opens the local camera if needed and scrolls the robot into view. Large overlays guide eight positions: centre, left, right, up, down, near, far and diagonal. Y accepts/advances, X freezes, arrows correct, Shift uses 5° steps, Escape cancels/exits and Enter closes completion. Permission and lost-face instructions are explicit; no sample is saved without a fresh observation.'),
      ('surface',bool(gaze.get('passed') and desk.get('passed')),'Smooth housing, friendly neck and clean black/white base seam','Curved shell profiles are subdivided, normals are smooth, and black/white material boundaries share exactly the same 96-vertex ring. No intersecting lower sleeve remains. The bottom lip and neck fairing are rounded; the status light is a curved capsule. A CPU z-buffer replaces polygon-only depth sorting, and the face texture is perspective-correct and bilinearly sampled. Unchanged housing is cached; redundant canvas clears are avoided.'),
      ('names',bool(prompt.get('passed')),'Natural naming instead of a mandatory name prefix','Removed the code that forcibly prepended a name and the conflicting prompt instructions. Keep authoritative identity metadata, but normally omit vocatives. Names remain available for introductions, identity questions and actual disambiguation. Prompt rules also distinguish spoken numbers from silent timing cues. The configured Luna provider/model is unchanged.'),
      ('interrupt',stop_ok,'Voice stop by the current addressee only','Keep native TYGER GRU/Second Ear BARGE as the primary signal, using the existing DAC/sample-tagged playback reference with device latency. Compare a candidate against all enrolled references AND the bot, but authorize only the current reply addressee. A bounded native ASR batch checks the continuous signal and two acoustic views with silence padding. Probe-only linear echo suppression requires strongly correlated quiet playback frames; otherwise no subtraction is used. Literal words never bypass identity checks. Longer phrases need stronger fast-speaker evidence than short words. A verified stop cancels playback/generation; late packets are rejected by reply ID and no new reply is generated. Eight positive/negative synthetic cases and final source stability are required; this is not human authentication.'),
    ]
    checks=[('Real Luna function calls',tools.get('passed'),str(len(tools.get('cases',[])))+' install/ordinary/cancel cases'),
      ('Pinned local CPU Laya worker',semantic.get('local_model_verified'),str(semantic.get('local_model_health',{}))),
      ('Hybrid explicit-stop and mention controls',semantic.get('explicit_stop_and_controls_passed'),str(semantic.get('cases',[]))),
      ('Generic meaning-dependent rule control',semantic.get('passed'),'All cases must pass; a failed generic semantic-rule control stays visible'),
      ('Spoken proactive interruption / negative controls',proactive_ok,str(len(proactive.get('cases',[])))+' cases on current runtime source'),
      ('Offline unit contracts',unit.get('passed'),str(unit.get('tests'))+' tests'),
      ('Camera capture / CPU inference budget',gaze.get('camera_rate',{}).get('maximum_requested_fps')==10,str(gaze.get('camera_rate',{}))),
      ('Real MediaPipe runtime / fake camera',bool(camera.get('camera_video_running') and camera.get('camera_capture_fps',100)>0 and camera.get('camera_capture_fps',100)<=10.1 and not camera.get('page_errors')),
        str({k:camera.get(k) for k in ('camera_status','camera_capture_fps','hardware_accuracy')})),
      ('Eye tracking, calibration and tutorial',gaze.get('passed'),str(gaze.get('ui',{}))),
      ('CPU 3D, expressions and mobile layout',desk.get('passed'),str({k:desk.get(k) for k in ['unique_expression_renders','render_p95_ms','initial_eye_contact_error_degrees','mobile_no_overflow']})),
      ('Luna instruction/naming checks',prompt.get('passed'),str(len(prompt.get('cases',[])))+' explicit cases'),
      ('Actual browser microphone/settings',mic.get('passed'),'Public synthetic fake-device audio, not a physical microphone'),
      ('Authorized and denied spoken stops',stop_ok,str(len(stop.get('cases',[])))+' cases; details below'),
      ('Frozen-source current-task QA',bool(active.get('passed') and active.get('runtime_source_sha256')==signature and active.get('source_unchanged')),
        str([{k:s.get(k) for k in ('name','passed','seconds')} for s in active.get('stages',[])]))]
    visual_browser=read(ROOT/'logs/multimodal-browser-checks.json');visual_live=read(ROOT/'logs/multimodal-live-checks.json')
    visual_ok=bool(visual_browser.get('passed') and visual_live.get('passed') and len(visual_live.get('cases',[]))>=8 and visual_live.get('runtime_source_sha256')==signature)
    tasks.append(('multimodal',visual_ok,'Additive multi-face / visual speaker identity','Existing CPU MediaPipe runs in a worker with four face tracks. Lip/jaw motion is evaluated temporally, not static mouth state. A lazy CPU face-api recognition worker links named, acoustically verified introductions to a common person ID. Three independent default-on persisted settings control offscreen filtering, gaze and unknown greetings. Default biometrics are RAM-only; explicit consent is required for browser persistence, with withdrawal and Forget all. See the dedicated multimodal report for measured scope, real-model performance, privacy and physical-validation limits.'))
    checks.append(('Multimodal browser + current eight live conditions',visual_ok,'Real CPU models, synthetic landmark behavior and real ASR/TTS with timestamped synthetic visual observations; not physical room accuracy. /static/multimodal-report.html'))
    checks_complete=all(bool(c[1]) for c in checks)
    complete=all(t[1] for t in tasks) and checks_complete
    verification_ok=all(t[1] for t in tasks) and checks_complete
    tasks.append(('verification',verification_ok,'Final targeted verification and handoff','Run offline contracts, actual Chromium UI/microphone checks, public-synthetic streamed-echo/stop scenarios and Luna tool checks. Keep failures and limits visible; publish an audited source ZIP. No physical camera/microphone or held-out human speaker accuracy is claimed. Generic semantic-rule accuracy and short-word identity reliability remain separate from local worker availability.'))
    e=lambda x:html.escape(str(x))
    out='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Robby worklog and verification</title><style>body{font:16px/1.6 system-ui;max-width:1100px;margin:24px auto;padding:20px;background:#f8f7f3;color:#26343c}article{background:white;border:1px solid #d8dfdc;border-left:5px solid #c89b44;border-radius:14px;padding:16px 20px;margin:14px 0}article.done{border-left-color:#4e8b6c}h1,h2{line-height:1.3}h2{font-size:20px}input{accent-color:#4e8b6c}a{color:#356b79}td,th{padding:9px;border:1px solid #ddd;text-align:left}table{border-collapse:collapse;background:white}pre{white-space:pre-wrap;font-size:12px}.scroll{overflow:auto}</style><nav><a href="/desk-robot/">Open 3D Robby</a> · <a href="/static/threshold-replay.html">Speaker sensitivity</a> · <a href="/downloads/robby-source.zip">Audited source ZIP</a></nav><h1>Robby: tasks, solutions and verification</h1>'''
    out+='<p>Updated '+e(datetime.datetime.now(datetime.timezone.utc).isoformat())+'. Scope: the active eye-contact, surface, guided calibration, interruption and naming requests of October 21, 2026—not a claim that every historical research task is finished.</p>'
    for ident,done,title,body in tasks:
        out+=f'<article id="{ident}" class="'+('done' if done else 'working')+'"><h2><input type="checkbox" disabled '+('checked' if done else '')+'>'+e(title)+'</h2><p>'+e('Verified in targeted synthetic tests' if done else 'In progress / final verification still pending')+'</p><p>'+e(body)+'</p></article>'
    out+='<h2>Current receipts</h2><div class="scroll"><table><tr><th>Check</th><th>Passed</th><th>Observed scope</th></tr>'+''.join('<tr>'+''.join('<td>'+e(x)+'</td>' for x in row)+'</tr>' for row in checks)+'</table></div>'
    out+='<h2>Actual streamed stop-command replay</h2><p>One fresh session per case. Four authorized phrases plus other-enrolled and unknown speakers, each with long and short stop forms. Real streamed TTS, simulated 240-ms playback buffering, 120-ms acoustic delay and echo gain 0.05. Latency starts at the beginning of the whole input clip (including its initial quiet audio), not at the final recognized word. A pass here is development evidence, not a real-room false-acceptance rate.</p><div class="scroll"><table><tr><th>Fixture</th><th>May interrupt</th><th>Interrupted</th><th>Latency (s)</th><th>Extra spoken replies</th><th>Passed</th></tr>'
    for c in stop.get('cases',[]):
        out+='<tr>'+''.join('<td>'+e(v)+'</td>' for v in (c.get('command'),c.get('authorized'),c.get('interrupted'),c.get('interruption_latency_s'),c.get('new_spoken_replies'),c.get('passed')))+'</tr>'
    out+='</table></div>'
    out+='<h2>Live agreed-rule interruption · measured audio path</h2><p>The setup command is spoken through real ASR; Luna installs the rule with an actual function call. The long probe continues while Robby speaks. No test-only rule injection, replacement ASR or private recordings are used. A 320-ms scheduler does not imply a 320-ms response: native partials, acoustic identity context, semantic API when needed, TTS generation and DAC buffering all add delay.</p><div class="scroll"><table><tr><th>Condition</th><th>Interrupted</th><th>Decision after input start (s)</th><th>First audio after input start (s)</th><th>Spoke before user finished</th><th>Passed</th></tr>'
    for c in proactive.get('cases',[]):
        begin=c.get('user_start_s',0)
        delta=lambda key:round(c[key]-begin,3) if c.get(key) is not None else None
        out+='<tr>'+''.join('<td>'+e(v)+'</td>' for v in (c.get('condition'),c.get('interrupted'),delta('decision_at_s'),delta('first_new_audio_s'),c.get('spoken_before_user_end'),c.get('passed')))+'</tr>'
    out+='</table></div><p>Literal rules execute locally after a fresh matching partial and independent speaker verification. The first exploratory banana test took about 8.18 s from fixture start to decision and 9.92 s to virtual DAC audio; early ASR misrecognized the first word and short-window speaker cues delayed authorization. This is functional early interruption, not yet human-validated immediate response. Failed setup/earlier attempts remain archived. Semantic API measurements are listed above separately; they are not a promise of hop-rate network calls.</p><p>The first full four-condition replay exposed an unknown-voice false trigger: a strong fast cue rescued ECAPA cosine 0.497 through an overly permissive new branch. That branch was removed. Proactive interjections now need a strong teacher cosine of at least max(0.55, the configured normal threshold), 0.10 rival margin and a same-person independent fast cue of at least max(0.45, the configured fast threshold minus 0.17). This is a conservative development rule, not human-calibrated authentication. Normal-turn 0.32 remains unchanged. Cancellation instructions have precedence over topic triggers; clearing rules also clears stale decision UI state.</p>'
    out+='<h2>Eye-contact formula</h2><p>Assume a 65° horizontal field of view and a 63-mm eye baseline. Correct the eye-pair span for image aspect and relative z; estimate and clamp distance Z to 0.22–2.8 m. Let rayX/rayY be the eye-midpoint camera rays and g=Z/(Z+0.08). Fit each tangent angle with features [1, g·rayX/0.35, g·rayY/0.25, 0.35·(1/Z−1/0.65)]. Ridge regularization keeps the uncalibrated geometry as a prior, particularly for depth with few examples. The 80-mm pivot setback, IPD and FOV are explicit heuristics, not measured camera intrinsics. Calibration learns the residual offsets/coupling from your subjective confirmations.</p>'
    out+='<p>The tracker does not infer where your own eyes are looking: it directs Robby towards their position. Pure roll and nose movement do not drive his head. Camera and calibration geometry stay in this browser; only typed/transcribed conversation text reaches the configured Luna API.</p>'
    out+='<p>A teacher-only floor increase and a separately trained 3.04-s student were each insufficient for the retained timbre-confusable unknown voice. The final gate also keeps time-weighted sequential ECAPA evidence across the ongoing utterance, requiring mean cosine at least max(0.50, normal threshold minus 0.05). A genuine one-second acoustic pause, changed candidate or six seconds without a probe resets this state. Correlated windows are not independent statistical trials; no identity probability or held-out human accuracy is inferred. This avoids repeatedly forgetting early contrary evidence and waiting for a lucky passing window.</p>'
    out+='<p>A later sparse-partial replay exposed an accumulator bug: the first already-contextualized observation was given only 320-ms weight, while a later observation could receive four times that weight. The first context now starts at full bounded weight; a regression checks the sparse weak-then-strong sequence. A 0.50 long-student floor also missed the known voice at a borderline score; the development floor is 0.45, still with the same-ID/rival margin, strong latest teacher, cumulative teacher and fast checks. Both failed variants remain archived; these values are not fitted human operating points.</p>'
    out+='<p>An additional semantic replay returned after the unknown probe had already stopped; it exposed a separate stale-decision bug. Fresh audible speech is now required before a query and again at commitment. A delayed decision after speech ends cannot start an interjection. The regression explicitly makes the user go quiet while a semantic request is pending. These repairs do not turn experimental speaker similarity into authentication.</p>'
    out+='<p>The first new incoming-stop replay correctly decoded Stopp but rejected a phase-sensitive fast score of 0.396 with teacher cosine about 0.284. For brief ASR-confirmed one-word/repeated-word commands only, the fast floor is now 0.35 and joint product 0.10. Teacher minimum, current-addressee/rival/bot guards remain; longer phrases retain fast floor max(0.58, configured fast threshold minus 0.04) and product 0.12. A regression checks that boundary and a mismatching fast identity. The actual positive and foreign-speaker replays below decide whether the revision passes, not that regression alone.</p>'
    out+='<p>The following replay caught a stale unknown short stop accepted more than two seconds after its clip ended. Local literal stops now require the last audible frame within 800 ms of their ASR capture endpoint; old 3.04-s windows cannot be re-decoded indefinitely until their identity score happens to improve. Longer phrases use a balanced stronger joint gate: teacher at least max(0.30, normal threshold minus 0.15), fast at least max(0.40, fast threshold minus 0.22), product at least 0.18, plus the existing rival/current-addressee/bot checks. This replaced the preceding fast-dominated long-phrase variant, which missed the repeat-stop fixture.</p>'
    out+='<p>A separate other-enrolled short-stop run began while a second greeting reply was still pending, so its supposed Christoph reply was actually addressed to Robert. That setup is invalid as an identity test, not proof that Robert interrupted Christoph. The harness now waits for all introduction endpoints to finish with a bounded quiet settling period and asserts the actual reply addressee before playing any stop. It does not replay fixtures until their speaker score improves. The earlier receipt and queued-introduction behavior remain visible rather than being silently counted as a pass.</p>'
    out+='<h2>Where early-interruption time is spent</h2><div class="scroll"><table><tr><th>Positive run</th><th>First native banana partial after input start</th><th>Then waiting for speaker/decision</th><th>Then TTS plus virtual DAC</th><th>Controller decision work</th></tr>'
    for c in proactive.get('cases',[]):
        if c.get('condition')!='positive' or not c.get('interrupted'):continue
        mentions=[x['at_s'] for x in c.get('events',[]) if x.get('phase')=='probe' and x.get('type')=='asr_preview' and x.get('source')=='native_asr' and 'bananen' in x.get('text','').lower()]
        decisions=[x.get('decision',{}) for x in c.get('events',[]) if x.get('type')=='interaction' and x.get('decision',{}).get('action')=='interrupt_user']
        if mentions:
            values=('Public synthetic banana speech',round(min(mentions)-c['user_start_s'],3),round(c['decision_at_s']-min(mentions),3),round(c['first_new_audio_s']-c['decision_at_s'],3),str(decisions[-1].get('decision_ms'))+' ms' if decisions else 'Unavailable')
            out+='<tr>'+''.join('<td>'+e(x)+'</td>' for x in values)+'</tr>'
    out+='</table></div><p>Intervals are seconds except controller work in milliseconds. Controller work includes acoustic verification and a semantic call when required; it is part of the preceding interval, not additive. Native partial frequency is not the 320-ms scheduler frequency. Input clips can contain initial silence. The virtual DAC includes 240-ms output buffering; no physical-device latency is inferred.</p>'
    if any(c.get('condition')=='unknown' and c.get('first_new_audio_s') is not None for c in proactive.get('cases',[])):
        out+='<p><strong>Separate retained limitation:</strong> the unknown-voice control did not trigger a live agreed-rule interjection, but the deliberately permissive ordinary post-pause conversation gate admitted this timbre-confusable synthetic voice and later produced normal reply audio. The four-condition pass covers proactive interruption, not perfect background rejection on every dialogue path. The ordinary 0.32 setting is unchanged as requested; stronger speaker discrimination and held-out human calibration remain necessary.</p>'
    out+='<h2>Rendering observations</h2><pre>'+e(json.dumps(gaze.get('renderer',{}),indent=2))+'</pre><p>Static-frame identity was tested with a held neutral pose. Motion and static timings differ; CPU/browser load matters. This is not a guarantee that every webcam/browser is flicker-free.</p>'
    out+='<h2>Retained problems and limitations</h2><p>The first single-word Stopp replay was detected by TYGER but rejected by the old 480-ms voiced-duration requirement. The public synthetic clip contained only about 180 ms above that gate. Separate ECAPA checks also showed that very short synthetic utterances can have unreliable speaker similarity. Short-command rules must therefore be tested against other enrolled and background speakers—not simply given a low threshold. Exploratory failed stop attempts remain in speaker-live-results/stop-attempt-*.json. A temporary diagnostic-code syntax error caused a fallback run; that run is invalid, not speaker-performance evidence. Compilation checks and explicit active-hybrid assertions now precede/guard the replay.</p>'
    out+='<p>A permissive short-command prototype falsely accepted an unknown background voice; it was rejected. Stronger fast-speaker evidence is now required for longer phrases. Aggressive peak cropping also caused missed consonants and empty/malformed ASR; continuous and fixed acoustic views plus silence padding replaced that single fragile view. The original and clearer short Pause fixtures remained inconsistently recognized, so neither is counted as a validated positive; use the measured phrases above. Global teacher centering, duration-vector averaging and cyclic short-signal context were explored offline but not deployed. None supplied a convincing general improvement.</p>'
    out+='<p>The background-stop negative exposed a separate bypass: a queued, already-transcribed stop used ordinary full-turn identity admission and called BARGE directly. At the intentionally permissive 0.32 normal-turn threshold this could admit a background stop even though the dedicated interruption verifier had rejected it. Queued stops now call exactly the same current-addressee/teacher/fast/playback verifier, using the original speech timestamp. Idle stale stop transcripts do not create a new acknowledgment or spoken reply. A dedicated offline regression locks this contract.</p>'
    out+='<p>A same-owner sentence tail arriving during final ASR could previously queue a second reply. Contiguous verified-owner tracks now merge before submission, invalidating stale crops/embeddings and keeping the successor’s own quiet deadline. Different people and real long pauses are not merged. One attempted replay overlapped a delayed graceful shutdown and is invalid setup, not model evidence. New stop replays check the owned backend start time against source modification times and record both PID and unchanged source hash.</p>'
    out+='<h2>Availability incident · October 21</h2><p>The Robby worker was left stopped during backend interruption work, causing the public tunnel to return HTTP 502. The owned worker was restarted without restarting the shared TTS service or changing the public hostname. Recovery checks returned HTTP 200 locally and through HTTPS; the backend reported ready with speaker identity available. A fresh Chromium test through the public URL passed all 40 expression renders, frontal pose, mechanical controls and mobile layout with no JavaScript errors. This recovery check does not by itself verify a physical microphone conversation or the pending short-command experiments. Future backend restarts must pair stop/start immediately, then verify readiness and the public route before any further experiments.</p>'
    out+='<p>The initial naming regression returned the correct user plus irrelevant other names. The prompt now requests only the verified name for a direct identity question. A separate malformed spoken-temperature output exposed ambiguous numeric-tag instructions, which were clarified. The final measured checks are listed above; no failure is counted as a pass.</p>'
    out+='<h2>Primary implementation references</h2><p><a href="https://github.com/google-ai-edge/mediapipe/blob/master/docs/solutions/face_mesh.md">MediaPipe landmark coordinates</a> · <a href="https://github.com/nineninesix-ai/tyger-s2s/blob/main/DEVELOPING.md">TYGER Second Ear and BARGE</a> · <a href="https://github.com/nineninesix-ai/tyger-s2s/blob/main/scripts/validate/second_ear.py">TYGER validation</a> · <a href="https://developers.openai.com/api/docs/guides/prompt-engineering">OpenAI Docs: explicit, consistent instructions</a>. The prompt guidance was used to remove contradictory naming rules, not to change models/endpoints.</p>'
    out+='<p>The <a href="https://developers.openai.com/api/docs/guides/function-calling">official function-calling guide</a> informed strict bounded schemas, real tool result messages and the final spoken acknowledgment. This changes the conversational capability, not the configured Luna model/provider.</p>'
    before_chunks=read(ROOT/'logs/tts-chunk-before-reserve.json')
    out+='<h2>Streaming playback reserve · synthetic typed HTTPS turns</h2><table><tr><th>Condition</th><th>PCM chunk seconds</th><th>Scheduling gaps over 20 ms</th><th>Largest gap (ms)</th></tr>'
    for label,record in [('1.6-s chunks, device-only lead',before_chunks),('1.6-s chunks, 450-ms initial reserve',chunks)]:
        out+='<tr>'+''.join('<td>'+e(value)+'</td>' for value in [label,', '.join(str(round(c['seconds'],3)) for c in record.get('chunks',[])),str(record.get('scheduled_gap_count','not measured')),str(round(record.get('max_scheduled_gap_ms',0),1))])+'</tr>'
    out+='</table><p>These are individual synthetic typed-reply checks, not a statistical benchmark or a physical-device listening test. PCM durations include codec/resampling effects; the first and final blocks can be shorter. The reserve adds startup latency but is not applied anew to each chunk. Longer transport stalls can still cause underruns.</p>'
    receipt={'generated':datetime.datetime.now(datetime.timezone.utc).isoformat(),'runtime_source_sha256':runtime_signature(),
        'all_selected_checks_passed':checks_complete,'all_selected_tasks_complete':complete,
        'physical_camera_or_microphone_used':False,'tasks':[{'id':a,'done':b,'title':c} for a,b,c,d in tasks], 'checks':checks}
    (ROOT/'logs/worklog-verification.json').write_text(json.dumps(receipt,indent=2))
    out+='<p><a href="/static/speed-and-tools.html">Latest speed, public tools and flexible speaker update</a> · <a href="/static/visual-onboarding-update.html">Visible-speaker onboarding fix and recovery tests</a> · <a href="/static/live-follow-update.html">Continuous-interruption and real camera-to-head test results</a>. Earlier experimental failures above remain historical evidence, not claims that every old variant is deployed.</p>'
    out+='<details><summary>Machine-readable verification</summary><pre>'+e(json.dumps(receipt,indent=2))+'</pre></details></html>'
    (ROOT/'static/worklog.html').write_text(out)
    print(json.dumps({'complete':complete,'tasks_done':sum(t[1] for t in tasks),'tasks':len(tasks)}))

